SET NAMES utf8mb4;

CREATE TABLE users (
    id INT NOT NULL AUTO_INCREMENT,
    username VARCHAR(50) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role ENUM('user', 'admin') NOT NULL DEFAULT 'user',
    PRIMARY KEY (id)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE private_notes (
    user_id INT NOT NULL,
    ciphertext BLOB NOT NULL,
    nonce BINARY(12) NOT NULL,
    auth_tag BINARY(16) NOT NULL,
    PRIMARY KEY (user_id),
    CONSTRAINT fk_private_notes_user FOREIGN KEY (user_id)
        REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE destinations (
    destination_id INT NOT NULL AUTO_INCREMENT,
    destination_name VARCHAR(100) NOT NULL,
    geographical_category VARCHAR(20) NOT NULL,
    administrative_region VARCHAR(100) NOT NULL,
    short_description TEXT NOT NULL,
    image_path VARCHAR(255) NOT NULL,
    image_alt VARCHAR(255) NOT NULL,
    detailed_description TEXT NULL,
    location VARCHAR(255) NULL,
    highlights TEXT NULL,
    admin_id INT NULL DEFAULT NULL,
    PRIMARY KEY (destination_id),
    CONSTRAINT fk_destinations_admin FOREIGN KEY (admin_id)
        REFERENCES users(id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO destinations (
    destination_id, destination_name, geographical_category,
    administrative_region, short_description, image_path, image_alt,
    detailed_description, location, highlights
) VALUES
    (1, 'الرياض', 'central', 'منطقة الرياض', 'أبراج حديثة وأسواق عريقة تجمع بين عمارة العاصمة الحديثة وتراث نجد.', 'assets/images/riyadh-new.png', 'أفق مدينة الرياض عند الغروب، ويظهر برجا المملكة والفيصلية', 'الرياض عاصمة المملكة العربية السعودية، وتجمع بين المباني الحديثة والمعالم التي تعكس تاريخ نجد. وتتيح متاحفها وأسواقها التقليدية التعرف على جوانب من تاريخ المملكة وحرفها وتراثها المحلي.', 'منطقة الرياض، وسط المملكة العربية السعودية', '<li>قصر المصمك: معلم تاريخي بارز في قلب الرياض القديمة.</li>
<li>المتحف الوطني السعودي: متحف يعرض جوانب من تاريخ الجزيرة العربية وتراثها.</li>
<li>سوق الثميري: سوق تقليدي يضم محلات للحرف والمنتجات التراثية.</li>'),
    (2, 'الدرعية', 'central', 'منطقة الرياض', 'تعرّف على العمارة النجدية وأزقة الدرعية ومباني حي الطريف التاريخية.', 'assets/images/diriyah-new.png', 'مبانٍ طينية وأبراج بالعمارة النجدية في الدرعية أمام أشجار النخيل', 'تتميز الدرعية بعمارتها النجدية ومبانيها الطينية التي تعكس جانبًا من تراث وسط المملكة. ويبرز حي الطريف وقصوره بوصفه مركزًا للحكم في الدولة السعودية الأولى، بينما يطل البجيري على المشهد التراثي للمنطقة.', 'منطقة الرياض، إلى الشمال الغربي من مدينة الرياض، على ضفاف وادي حنيفة', '<li>حي الطريف: حي تاريخي يعكس العمارة النجدية وتاريخ الدولة السعودية الأولى.</li>
<li>قصر سلوى: قصر تاريخي يقع داخل حي الطريف.</li>
<li>مطل البجيري: منطقة تضم مطاعم ومقاهي بإطلالة على حي الطريف.</li>'),
    (3, 'مكة المكرمة', 'western', 'منطقة مكة المكرمة', 'تضم مكة المكرمة المسجد الحرام والكعبة المشرفة، قبلة المسلمين.', 'assets/images/makkah_enhanced.jpg', 'الكعبة المشرفة في المسجد الحرام بمكة المكرمة ويظهر برج الساعة خلفها', 'تحتضن مكة المكرمة المسجد الحرام والكعبة المشرفة، ويتوجه إليها المسلمون لأداء الحج والعمرة. وتضم المدينة جبالًا ومواقع تاريخية مرتبطة بالسيرة النبوية، من أبرزها جبل النور وجبل ثور.', 'منطقة مكة المكرمة، غرب المملكة العربية السعودية، إلى الشرق من مدينة جدة', '<li>المسجد الحرام: يضم الكعبة المشرفة، قبلة المسلمين.</li>
<li>جبل النور: جبل يقع في شمال شرق مكة المكرمة ويضم غار حراء.</li>
<li>جبل ثور: جبل يقع جنوب المسجد الحرام ويضم غار ثور المرتبط بالهجرة النبوية.</li>'),
    (4, 'جدة', 'western', 'منطقة مكة المكرمة', 'تتميز جدة بإطلالاتها على البحر الأحمر وواجهتها البحرية، إلى جانب معالمها التاريخية.', 'assets/images/jeddah-corniche.jpg', 'واجهة جدة البحرية على البحر الأحمر، مع أشجار النخيل والأبراج وأمواج البحر.', 'تقع جدة على ساحل البحر الأحمر، وتجمع بين الأحياء التاريخية والواجهات البحرية الحديثة. وتمنح مباني البلد وأسواقها التقليدية، إلى جانب مسارات التنزه المطلة على البحر، الزائر فرصة للتعرف على تراث المدينة وطابعها الساحلي.', 'منطقة مكة المكرمة، على ساحل البحر الأحمر غرب المملكة العربية السعودية', '<li>جدة التاريخية «البلد»: منطقة تضم مباني تراثية وأسواقًا تقليدية.</li>
<li>واجهة جدة البحرية: منطقة ساحلية تضم مسارات للمشي ومساحات للتنزه.</li>
<li>نافورة الملك فهد: معلم بحري بارز على ساحل جدة.</li>'),
    (5, 'المدينة المنورة', 'western', 'منطقة المدينة المنورة', 'تعرّف على المسجد النبوي والمعالم التاريخية في المدينة المنورة.', 'assets/images/madinah_enhanced.jpg', 'القبة الخضراء ومآذن المسجد النبوي في المدينة المنورة', 'تحتضن المدينة المنورة المسجد النبوي، وترتبط معالمها بتاريخ الهجرة النبوية وبدايات المجتمع الإسلامي. وتضم مساجد ومواقع تاريخية بارزة، من بينها مسجد قباء وجبل أحد، تتيح التعرف على جوانب من السيرة النبوية.', 'منطقة المدينة المنورة، غرب المملكة العربية السعودية، إلى الشمال من مكة المكرمة', '<li>المسجد النبوي: مسجد النبي محمد صلى الله عليه وسلم وأبرز معالم المدينة.</li>
<li>مسجد قباء: مسجد تاريخي يقع جنوب المدينة المنورة.</li>
<li>جبل أحد: جبل بارز شمال المدينة، ارتبط اسمه بغزوة أحد.</li>'),
    (6, 'العلا', 'western', 'منطقة المدينة المنورة', 'تشتهر العلا بمواقعها الأثرية وتكويناتها الصخرية، ومن أبرز معالمها جبل الفيل.', 'assets/images/alula-new.png', 'صخرة الفيل في العلا عند غروب الشمس', 'تتميز العلا بتاريخها العريق ومواقعها الأثرية وتكويناتها الصخرية الفريدة. وتضم مجموعة من المعالم التي تعكس الإرث الحضاري والطبيعي للمنطقة.', 'منطقة المدينة المنورة، شمال غرب المملكة العربية السعودية', '<li>الحِجر: موقع أثري يضم مقابر نبطية منحوتة في الصخور، وهو أول موقع سعودي أُدرج في قائمة التراث العالمي لليونسكو.</li>
<li>جبل الفيل: تكوين صخري طبيعي يشبه شكل الفيل.</li>
<li>البلدة القديمة: منطقة تاريخية تضم مباني وممرات قديمة.</li>'),
    (7, 'الدمام', 'eastern', 'المنطقة الشرقية', 'يوفّر كورنيش الدمام ممرات للتنزّه بين النخيل والمساحات الخضراء بمحاذاة الخليج العربي.', 'assets/images/dammam-new.png', 'ممشى كورنيش الدمام بمحاذاة البحر، تحفّه أشجار النخيل والمساحات الخضراء', 'تطل الدمام على الخليج العربي، ويبرز طابعها الساحلي في كورنيشها وحدائقها البحرية. وتضم المدينة مساحات للتنزه والمشي بمحاذاة البحر، إلى جانب جزيرة المرجان التي تعد من معالمها المعروفة.', 'المنطقة الشرقية، على ساحل الخليج العربي شرق المملكة العربية السعودية', '<li>كورنيش الدمام: امتداد ساحلي يضم مساحات للتنزه وإطلالات على الخليج العربي.</li>
<li>جزيرة المرجان: جزيرة اصطناعية قرب الكورنيش، تتميز بمعلم الفنار.</li>
<li>متنزه الملك عبدالله البحري: متنزه على الواجهة البحرية يضم مساحات خضراء وممرات للمشي.</li>'),
    (8, 'الخبر', 'eastern', 'المنطقة الشرقية', 'تتميز الخبر بحدائقها الساحلية وإطلالاتها البحرية، ويُعد كورنيشها من أبرز أماكن التنزّه.', 'assets/images/khobar-new.png', 'نخيل وأحواض مياه وأزهار في حدائق كورنيش الخبر', 'تتميز الخبر بإطلالتها على الخليج العربي وواجهتها البحرية التي تضم مساحات خضراء وممرات للمشي. وتجمع وجهاتها بين التنزه على الكورنيش والتعرف على العلوم بأسلوب تفاعلي في مركز سايتك.', 'المنطقة الشرقية، على ساحل الخليج العربي إلى الجنوب من مدينة الدمام', '<li>كورنيش الخبر: واجهة ساحلية تضم ممرات للمشي ومساحات خضراء.</li>
<li>مركز سلطان بن عبدالعزيز للعلوم والتقنية «سايتك»: مركز يقدم العلوم من خلال معروضات وتجارب تفاعلية.</li>
<li>برج المياه: معلم معماري بارز بمحاذاة كورنيش الخبر.</li>'),
    (9, 'الظهران', 'eastern', 'المنطقة الشرقية', 'يضم مركز الملك عبدالعزيز الثقافي العالمي «إثراء» معارض ومكتبة، ويتميّز بعمارته اللافتة.', 'assets/images/dhahran-new.png', 'الواجهة الخارجية لمركز الملك عبدالعزيز الثقافي العالمي إثراء في الظهران', 'ترتبط الظهران بتاريخ صناعة النفط في المملكة، وتضم مركز الملك عبدالعزيز الثقافي العالمي «إثراء» ذا العمارة المميزة. ويجمع المركز مرافق ثقافية وتعليمية متنوعة، من بينها المتحف والمكتبة ومعرض الطاقة، للتعرف على الفنون والمعرفة والعلوم.', 'المنطقة الشرقية، بالقرب من مدينتي الدمام والخبر شرق المملكة العربية السعودية', '<li>متحف إثراء: مرفق داخل مركز إثراء يضم قاعات للمعارض الفنية والثقافية.</li>
<li>مكتبة إثراء: مكتبة داخل المركز تتيح التعرف على مجالات متنوعة من المعرفة.</li>
<li>معرض الطاقة: معرض ضمن مرافق إثراء يعرّف الزوار بعلوم الطاقة وصناعة النفط بأسلوب تفاعلي.</li>'),
    (10, 'جبال فيفا', 'southern', 'جازان', 'جبال خضراء ومدرجات زراعية وقرى جبلية تتميز بإطلالاتها الطبيعية.', 'assets/images/mountains-new.png', 'جبال خضراء ومدرجات زراعية في منطقة جازان.', 'تتميز جبال فيفا بمدرجاتها الزراعية وغطائها النباتي وبيوتها الحجرية ذات التصاميم الأسطوانية. وتضم مواقع مرتفعة تطل على المنحدرات والجبال المجاورة، إلى جانب متنزهات تتيح الاستمتاع بطبيعة المنطقة.', 'محافظة فيفاء في منطقة جازان، جنوب غرب المملكة العربية السعودية', '<li>العبسية: موقع مرتفع يتيح مشاهدة المنحدرات والجبال المحيطة.</li>
<li>السماع: موقع طبيعي من مواقع الإطلالة المعروفة في جبال فيفا.</li>
<li>متنزه قرضة: متنزه يضم مساحات خضراء وممرات للمشي وسط الطبيعة الجبلية.</li>'),
    (11, 'رجال ألمع', 'southern', 'منطقة عسير', 'قرية تراثية في منطقة عسير، تشتهر بعمارتها الحجرية المميزة وطابعها التاريخي بين الجبال.', 'assets/images/rijal-almaa-new.png', 'مبانٍ حجرية تراثية متعددة الطوابق بين جبال رجال ألمع.', 'تشتهر قرية رجال ألمع التراثية بمبانيها الحجرية متعددة الطوابق وزخارفها البيضاء التي تميز عمارتها المحلية. وتتيح أزقتها ومتحفها التعرف على جانب من تراث المنطقة وحياة أهلها، ضمن مشهد تحيط به جبال عسير.', 'محافظة رجال ألمع في منطقة عسير، غرب مدينة أبها في جنوب غرب المملكة العربية السعودية', '<li>قرية رجال ألمع التراثية: قرية تتميز بمباني حجرية متعددة الطوابق وأزقة تراثية.</li>
<li>متحف رجال ألمع: متحف يعرض مقتنيات تعكس التراث المحلي وحياة السكان.</li>
<li>كوخ العسل: وجهة ريفية في محافظة رجال ألمع تتيح للزوار التعرف على أنواع العسل المحلي وتذوقه، وسط إطلالات طبيعية جميلة.</li>'),
    (12, 'السودة', 'southern', 'منطقة عسير', 'تشتهر السودة بمرتفعاتها الجبلية وأجوائها الضبابية وإطلالاتها الطبيعية في منطقة عسير.', 'assets/images/alsoudah-new.png', 'مرتفعات السودة الجبلية وسط الغيوم والضباب في منطقة عسير.', 'تتميز السودة بمرتفعاتها الجبلية وغابات العرعر، ويضفي الضباب على مشاهدها الطبيعية طابعًا مميزًا. وتضم المنطقة مواقع للتنزه ومسارات وسط الطبيعة، وتطل مرتفعاتها على الجبال والأودية المحيطة.', 'منطقة عسير، بالقرب من مدينة أبها في جنوب غرب المملكة العربية السعودية', '<li>جبل السودة: معلم جبلي بارز يطل على المرتفعات والأودية المحيطة.</li>
<li>متنزه السودة: متنزه طبيعي يتميز بأشجار العرعر ومسارات التنزه.</li>
<li>متنزه السحاب: متنزه جبلي بالقرب من السودة، يتميز بمشاهده الطبيعية وغطائه النباتي.</li>');
